def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1

    # The sparse color marks points; connect consecutive points on each row
    # and column with the other color.
    marker = min(counts, key=counts.get)
    out = [row[:] for row in grid]

    for r in range(h):
        points = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(points, points[1:]):
            for c in range(a + 1, b):
                out[r][c] = 2

    for c in range(w):
        points = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(points, points[1:]):
            for r in range(a + 1, b):
                out[r][c] = 2

    return out
